
-- Batch 3: More Asia + Central Asia recipes
INSERT INTO public.recipes (name, slug, country, continent, category, difficulty, prep_time, cook_time, servings, summary, history, ingredients, steps, tags, image_url) VALUES
('Lumpia', 'lumpia-philippines', 'Philippines', 'Asia', 'Appetizer', 'Easy', 30, 15, 6, 'Filipino spring rolls filled with savory pork and vegetables, fried until crispy golden.', 'Lumpia was brought to the Philippines by Chinese traders and adapted with local ingredients. It''s now an essential part of Filipino celebrations and family gatherings.', '["1 lb ground pork","1 cup carrots, shredded","1 cup cabbage, shredded","1 onion, diced","3 cloves garlic, minced","1 tbsp soy sauce","Spring roll wrappers","Oil for frying","Sweet chili sauce for dipping"]'::jsonb, '["Sauté garlic and onion, add pork and cook through","Add vegetables, soy sauce, cook until tender","Cool filling completely","Wrap in spring roll wrappers, seal with water","Deep fry until golden brown","Serve with sweet chili sauce"]'::jsonb, ARRAY['Filipino','Spring Rolls','Appetizer','Fried'], 'https://images.unsplash.com/photo-1544025162-d76694265947?w=800'),

('Samosa', 'samosa-india', 'India', 'Asia', 'Appetizer', 'Medium', 40, 20, 12, 'Crispy triangular pastries stuffed with spiced potatoes and peas, deep-fried to perfection.', 'Samosas traveled from Central Asia to India via trade routes in the 13th century. They became one of India''s most iconic snacks, served at every tea stall and celebration.', '["3 cups all-purpose flour","3 large potatoes, boiled and mashed","1 cup green peas","1 tsp cumin seeds","1 tsp garam masala","1 green chili, minced","Fresh cilantro","Oil for frying","Salt to taste"]'::jsonb, '["Make dough with flour, oil, and water; rest 30 minutes","Mix potatoes with peas, spices, chili, and cilantro","Roll dough, cut into semi-circles","Form cones, fill with potato mixture, seal","Deep fry at 350°F until golden and crispy","Serve with mint chutney and tamarind sauce"]'::jsonb, ARRAY['Indian','Street Food','Vegetarian','Fried'], 'https://images.unsplash.com/photo-1601050690117-94f5f6fa8bd7?w=800'),

('Dosa', 'dosa-india', 'India', 'Asia', 'Breakfast', 'Medium', 480, 10, 4, 'A crispy fermented rice and lentil crepe from South India, served with sambar and chutney.', 'Dosa dates back over 2,000 years in South Indian cuisine. The fermentation process was a natural preservation technique that also created the distinctive sour flavor and crispy texture.', '["2 cups rice","1 cup urad dal (black gram)","1/2 tsp fenugreek seeds","Salt to taste","Oil or ghee for cooking","Potato masala for filling","Coconut chutney and sambar for serving"]'::jsonb, '["Soak rice and dal separately for 6 hours","Grind to a smooth batter, ferment overnight","Add salt, the batter should be bubbly","Heat a flat griddle, spread thin layer of batter in circular motion","Drizzle oil around edges","Cook until golden and crispy on bottom","Add potato masala if making masala dosa","Fold and serve with coconut chutney and sambar"]'::jsonb, ARRAY['South Indian','Fermented','Breakfast','Vegetarian','Crepe'], 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?w=800'),

('Dal', 'dal-india', 'India', 'Asia', 'Main Course', 'Easy', 10, 30, 4, 'A comforting spiced lentil stew, the everyday staple of Indian cuisine.', 'Dal has been a protein staple in the Indian subcontinent for millennia, especially important in vegetarian traditions. Every region and family has their own version, making it one of the most diverse dishes in Indian cooking.', '["1 cup red or yellow lentils","3 cups water","1 tsp turmeric","1 onion, diced","2 tomatoes, chopped","3 cloves garlic, minced","1 inch ginger, grated","1 tsp cumin seeds","2 tbsp ghee","Fresh cilantro","Salt to taste"]'::jsonb, '["Wash lentils and cook with water and turmeric until soft","In a separate pan, heat ghee and pop cumin seeds","Add onion, garlic, ginger; sauté until golden","Add tomatoes, cook until soft","Pour tempering over cooked lentils","Simmer together for 5 minutes","Season with salt, garnish with cilantro","Serve with rice or naan"]'::jsonb, ARRAY['Indian','Lentils','Vegetarian','Comfort Food','Staple'], 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?w=800'),

('Chole', 'chole-india', 'India', 'Asia', 'Main Course', 'Medium', 15, 40, 4, 'A robust North Indian chickpea curry with complex spices, commonly paired with bhature.', 'Chole Bhature is a Punjabi classic that became one of North India''s most popular street foods. The spice blend (chole masala) varies by family, passed down through generations.', '["2 cans chickpeas, drained","2 onions, finely chopped","3 tomatoes, pureed","2 tbsp chole masala","1 tsp garam masala","2 tea bags (for color)","2 tbsp oil","1 inch ginger, grated","4 cloves garlic, minced","Fresh cilantro and onion rings for garnish"]'::jsonb, '["Brew tea bags in 1/2 cup water, set aside","Heat oil, sauté onions until deep golden","Add ginger-garlic, cook 2 minutes","Add tomato puree, cook until oil separates","Add chole masala and garam masala","Add chickpeas and tea water","Simmer for 25-30 minutes until thick","Garnish with cilantro and onion rings","Serve with bhature or rice"]'::jsonb, ARRAY['North Indian','Punjabi','Chickpea','Vegetarian','Street Food'], 'https://images.unsplash.com/photo-1585937421612-70a008356fbe?w=800'),

('Pulao', 'pulao-india', 'India', 'Asia', 'Main Course', 'Easy', 15, 25, 4, 'A fragrant one-pot rice dish cooked with whole spices, vegetables or meat.', 'Pulao has ancient origins in the Indian subcontinent, with references in Sanskrit texts. Unlike biryani which is layered, pulao is a single-pot preparation where rice and ingredients cook together.', '["2 cups basmati rice","Mixed vegetables or chicken","2 tbsp ghee","1 bay leaf","4 cardamom pods","4 cloves","1 cinnamon stick","1 onion, sliced","1 tsp cumin seeds","3.5 cups water","Salt to taste"]'::jsonb, '["Wash and soak rice for 20 minutes","Heat ghee, add whole spices until fragrant","Add onion, sauté until golden","Add vegetables or meat, cook briefly","Add drained rice, stir gently","Add water and salt, bring to boil","Cover and cook on low for 15-18 minutes","Let rest 5 minutes, fluff with fork"]'::jsonb, ARRAY['Indian','Rice','One-Pot','Aromatic'], 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?w=800'),

('Curry', 'curry-india', 'India', 'Asia', 'Main Course', 'Medium', 15, 35, 4, 'A rich, aromatic sauce-based dish with complex spice blends, the heart of Indian cuisine.', 'The word "curry" comes from the Tamil "kari" meaning sauce. Indian curries encompass thousands of regional variations, each with distinct spice profiles reflecting local ingredients and traditions.', '["1 lb protein (chicken, paneer, or vegetables)","2 onions, blended","3 tomatoes, pureed","1 tbsp curry powder","1 tsp turmeric","1 tsp cumin","1 tsp coriander","1/2 cup yogurt","2 tbsp oil","Fresh cilantro","Salt to taste"]'::jsonb, '["Heat oil, cook onion paste until golden brown","Add turmeric, cumin, coriander, and curry powder","Cook spices for 2 minutes until fragrant","Add tomato puree, cook until oil separates","Add yogurt gradually, stirring constantly","Add protein of choice","Simmer for 20-25 minutes until cooked through","Garnish with fresh cilantro","Serve with rice or naan"]'::jsonb, ARRAY['Indian','Curry','Spiced','Versatile'], 'https://images.unsplash.com/photo-1585937421612-70a008356fbe?w=800'),

('Tandoori', 'tandoori-india', 'India', 'Asia', 'Main Course', 'Medium', 240, 25, 4, 'Yogurt and spice-marinated chicken cooked in a tandoor clay oven until charred and juicy.', 'Tandoori chicken was popularized in the 1940s by Kundan Lal Gujral at Moti Mahal restaurant in Delhi. The tandoor (clay oven) cooking method dates back 5,000 years to the Indus Valley Civilization.', '["1 whole chicken, cut into pieces","1 cup yogurt","2 tbsp tandoori masala","1 tsp turmeric","1 tbsp lemon juice","1 tbsp ginger-garlic paste","Red food coloring (optional)","2 tbsp oil","Chaat masala for garnish","Lemon wedges and onion rings"]'::jsonb, '["Score chicken pieces deeply with a knife","Mix yogurt with all spices, lemon juice, and ginger-garlic paste","Marinate chicken for at least 4 hours, preferably overnight","Preheat oven to 475°F or prepare grill","Cook chicken for 20-25 minutes, turning once","Baste with oil halfway through","Chicken should be charred on outside, juicy inside","Sprinkle with chaat masala","Serve with lemon wedges, onion rings, and mint chutney"]'::jsonb, ARRAY['Indian','Tandoor','Grilled','Marinated'], 'https://images.unsplash.com/photo-1599487488170-d11ec9c172f0?w=800'),

('Tikka Masala', 'tikka-masala-uk', 'United Kingdom', 'Europe', 'Main Course', 'Medium', 30, 30, 4, 'Chunks of grilled chicken in a creamy, spiced tomato sauce - a British-Indian classic.', 'Chicken Tikka Masala is often called Britain''s national dish. Its exact origin is debated between Glasgow and Birmingham, but it represents the beautiful fusion of Indian spices with British tastes.', '["1.5 lbs chicken breast, cubed","1 cup yogurt","2 tbsp tikka masala paste","1 can tomato sauce","1 cup heavy cream","1 onion, diced","3 cloves garlic, minced","1 tbsp garam masala","1 tsp paprika","Fresh cilantro","Butter and oil"]'::jsonb, '["Marinate chicken in yogurt and tikka paste for 2 hours","Grill or broil chicken until charred","Sauté onion and garlic in butter until soft","Add tomato sauce, garam masala, and paprika","Simmer for 15 minutes","Stir in heavy cream","Add grilled chicken pieces","Simmer for 10 more minutes","Garnish with cilantro, serve with naan and rice"]'::jsonb, ARRAY['British-Indian','Fusion','Creamy','Curry'], 'https://images.unsplash.com/photo-1565557623262-b51c2513a641?w=800'),

('Manti', 'manti-uzbekistan', 'Uzbekistan', 'Asia', 'Main Course', 'Hard', 60, 45, 6, 'Central Asian steamed dumplings filled with spiced lamb and onion, served with yogurt.', 'Manti are believed to have originated along the Silk Road, with variations found from Turkey to Korea. The Uzbek version features large, pleated dumplings steamed in a multi-tiered mantovarka.', '["3 cups flour","1 lb ground lamb","2 large onions, finely diced","1 tsp cumin","1/2 tsp black pepper","Salt to taste","1 cup yogurt","2 cloves garlic, minced","Butter for serving","Fresh dill"]'::jsonb, '["Make dough with flour, water, salt; rest 30 minutes","Mix lamb with onions, cumin, pepper, salt","Roll dough thin, cut into 4-inch squares","Place filling in center, pinch corners together","Steam in mantovarka or steamer for 40-45 minutes","Mix yogurt with garlic for sauce","Serve manti topped with yogurt sauce","Drizzle with melted butter and fresh dill"]'::jsonb, ARRAY['Uzbek','Central Asian','Dumplings','Steamed','Silk Road'], 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?w=800');
